return [{ json: { ts: new Date().toISOString(), session_id: 'reflection',
  employee_id: '', skill_id: 'reflection', service: 'reflection_pass',
  request_json: JSON.stringify({ batch: $('Gather Batch').first().json.batch_size }),
  result_summary: n + ' تحديث: ' + ((o.memory_writes || []).map(m => m.why).join(' | ')
    || o.skipped_reason || 'لا جديد') } }];

const b = $('POST Patch').first().json.body || {};
const rows = $input.all().map(i => i.json).filter(r => r && r.patch_id);
const t = rows.find(r => r.patch_id === b.patch_id);
if (!t) return [{ json: { ok: false, error: 'PATCH_NOT_FOUND' } }];
if (t.status !== 'pending') return [{ json: { ok: false, error: 'NOT_PENDING',
  status: t.status } }];
const d = String(b.decision || '').toLowerCase();
if (d !== 'approve' && d !== 'reject')
  return [{ json: { ok: false, error: 'INVALID_DECISION' } }];
return [{ json: { ok: true, row: { ...t, status: d === 'approve' ? 'approved' : 'rejected',
  reviewed_by: b.reviewer || 'owner', review_note: String(b.note || '').slice(0, 300),
  updated_at: new Date().toISOString() } } }];

const dec = $('Apply Patch Decision').first().json.row;
if (!dec || dec.status !== 'approved') return [];
const rows = $input.all().map(i => i.json).filter(r => r && r.skill_id);
const sk = rows.find(r => r.skill_id === dec.skill_id);
if (!sk) return [];
const parts = String(sk.version || '1.0.0').split('.');
parts[2] = String((Number(parts[2]) || 0) + 1);  // patch-level bump
const stamp = new Date().toISOString().slice(0, 10);
const marker = '## تحسينات معتمدة (طبقة متعلَّمة)';
let body = String(sk.body_md || '');
if (body.indexOf(marker) === -1) body += '\n\n' + marker + '\n';
body += '\n- ' + dec.proposed_text + '  \n  _(' + dec.patch_id + ' — اعتمدها '
  + (dec.reviewed_by || 'مالك الإجراء') + ' في ' + stamp + ')_\n';
return [{ json: { skill_id: sk.skill_id, version: parts.join('.'), status: sk.status,
  title_ar: sk.title_ar, title_en: sk.title_en, keywords: sk.keywords,
  profile_id: sk.profile_id, allowed_services: sk.allowed_services,
  approval_chain: sk.approval_chain, auto_execute: sk.auto_execute,
  sla_hours: sk.sla_hours, internal: sk.internal, body_md: body,
  created_by: sk.created_by, updated_at: new Date().toISOString() } }];
